import math
import statistics
import time
from taf.rfrl.procedures.resources.python.logger import log_input_and_output, log_result
from taf.rfrl.procedures.resources.python.comparer.exceptions import PowerSavingRequirementsNotMet
from taf.rfrl.procedures.resources.python.admin_info_model.admin_info_model import get_power_usage_for_rus


@log_input_and_output
def validate_power_usage_change(
        start_power_usage, end_power_usage, rmod_id=None, expected_reduction=None, expected_increase=None):
    """
    Validates whether there was expected reduction/increase in power usage on RUs.
    :param start_power_usage: dict with runtime RU id as a key and power usage at start of the test as a value
    :type start_power_usage: dict[str, float]
    :param end_power_usage: dict with runtime RU id as a key and power usage at end of the test as a value
    :type end_power_usage: dict[str, float]
    :param rmod_id: RMOD id where power will only be checked. Defaults to None, meaning power usage will be checked on
                    all RMODs
    :type rmod_id: str or int
    :param expected_reduction: expected reduction after enabling power feature. e.g. "30". Which stands for 30%
    :type expected_reduction: str or int
    :param expected_increase: expected increase after disabling power feature. e.g. "30". Which stands for 30%
    :type expected_increase: str or int
    :raises PowerSavingRequirementsNotMet: when power reduction/increase values do not match expectations
                                           or were not provided(reduction is lower than expected or
                                           increase is greater than expected).
    """

    if not expected_reduction and not expected_increase:
        raise PowerSavingRequirementsNotMet(
            "Neither of expected power reduction nor increase percentage value was given"
        )

    for ru, power_usage in start_power_usage.items():
        if rmod_id is not None and str(rmod_id) != ru.split("-")[-1]:
            continue

        power_usage_percentage_change = math.fabs(end_power_usage[ru] / power_usage * 100 - 100)
        log_result("Power usage {operation} for {rmod} by {result}%".format(
            operation="increased" if expected_increase else "reduced",
            rmod=ru,
            result=round(power_usage_percentage_change, 2))
        )
        if expected_reduction and power_usage_percentage_change <= float(expected_reduction) or \
                expected_increase and power_usage_percentage_change >= float(expected_increase):

            error_msg = "Power usage values did not meet expected {} of {}%, result was {}%".format(
                "increase" if expected_increase else "reduction",
                expected_increase if expected_increase else expected_reduction,
                round(power_usage_percentage_change, 2)
            )

            raise PowerSavingRequirementsNotMet(error_msg)


def calculate_avg_power_usage(connection, runtime_ru_dist_names, iteration=2):
    """
    Gets average of real time power usage of given RUs in specific amount of time.
    :param connection: AdminConnection object or if used, string name alias
    :type connection: AdminConnection or str
    :param runtime_ru_dist_names: runtime RU dist_names e.g.
                                  ["/MRBTS-1/RAT-1/RUNTIME_VIEW-1/MRBTS_R-1/EQM_R-1/APEQM_R-1/RMOD_R-1"]
    :type runtime_ru_dist_names: list
    :param iteration: number of measurements used for calculation average
    :type iteration: int
    :return: dictionary with power usage for all given RUs e.g. {"RMOD_R-1": 21.37}
    :rtype: dict
    """
    avg_power_usage = {}
    measurements = []

    for counter in range(iteration):
        measurements.append(get_power_usage_for_rus(connection, runtime_ru_dist_names))
        time.sleep(60.0)

    for runtime_ru in measurements[0]:
        avg_power_usage[runtime_ru] = statistics.mean(power_usage[runtime_ru] for power_usage in measurements)

    return avg_power_usage
